// ═══════════════════════════════════════════════════════════════
// غراس — مولّد «صيد البالون» — لعبة توليد بالرصيد المشترك
// ═══════════════════════════════════════════════════════════════
import Script from 'next/script';
import { redirect } from 'next/navigation';
import { createServerSupabase } from '@/lib/supabase/server';

/**
 * «صيد البالون» — مولّد ألعاب ذكي بنظام رصيد الألعاب المشترك.
 * نفس مسار «من سيربح المليون» حرفيًا: game-ai للتوليد، المعاينة مجانية،
 * والخصم عبر game-consume عند تشغيل اللعبة النهائية. لا استحقاق مستقلًا لها.
 * المحرك (مقلاع Canvas) منفصل عن المحتوى — لا سؤال مكتوبًا في الكود،
 * ونص السؤال الخارجي يُعرض بـtextContent فلا يُنفَّذ منه HTML. الصوت مؤجَّل بقرار.
 */
export const dynamic = 'force-dynamic';

const GAME_CSS = "@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;700;800;900&display=swap');\n:root{\n  --sage:#7A9E7E; --sage-dark:#5C7F60; --gold:#C9A84C; --cream:#FAF8F3;\n  --ink:#2E3A2F; --royal:#0D1B4C; --royal2:#16276B; --game-gold:#F3C64B;\n}\n*{margin:0;padding:0;box-sizing:border-box;font-family:'Cairo',sans-serif}\nbody{background:var(--cream);color:var(--ink);min-height:100vh}\n\n/* ===== مولّد ===== */\n.gen-wrap{max-width:680px;margin:0 auto;padding:28px 18px 60px}\n.brand{text-align:center;margin-bottom:26px}\n.brand .seed{font-size:44px;line-height:1}\n.brand h1{font-size:26px;font-weight:900;color:var(--sage-dark);margin-top:6px}\n.brand p{color:#7d8a7e;font-size:14px;margin-top:4px}\n.badge{display:inline-block;background:var(--gold);color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:20px;margin-top:8px}\n\n.card{background:#fff;border:1.5px solid #E8E4D8;border-radius:18px;padding:22px;margin-bottom:16px;box-shadow:0 2px 10px rgba(122,158,126,.07)}\n.card h2{font-size:16px;font-weight:800;color:var(--sage-dark);margin-bottom:12px;display:flex;align-items:center;gap:8px}\n.card h2 .num{background:var(--sage);color:#fff;width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:13px;flex-shrink:0}\n\n.tabs{display:flex;gap:8px;margin-bottom:14px}\n.tab{flex:1;padding:10px;border:1.5px solid #E8E4D8;border-radius:12px;background:#fff;font-weight:700;font-size:14px;cursor:pointer;color:#8a917f;transition:.2s}\n.tab.on{border-color:var(--sage);background:#F0F5F0;color:var(--sage-dark)}\n\n.drop{border:2px dashed #C8D4C9;border-radius:14px;padding:30px 16px;text-align:center;cursor:pointer;transition:.2s;background:#FBFCFA}\n.drop:hover,.drop.over{border-color:var(--sage);background:#F0F5F0}\n.drop .ic{font-size:34px}\n.drop p{font-size:14px;color:#6d7a6e;margin-top:8px;font-weight:500}\n.drop small{color:#a5aea0;font-size:12px}\n#fileInput{display:none}\n.thumbs{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}\n.thumb{position:relative;width:76px;height:96px;border-radius:10px;overflow:hidden;border:1.5px solid #E8E4D8}\n.thumb img{width:100%;height:100%;object-fit:cover}\n.thumb .x{position:absolute;top:4px;left:4px;background:rgba(0,0,0,.55);color:#fff;border:none;width:20px;height:20px;border-radius:50%;cursor:pointer;font-size:11px;line-height:1}\ntextarea{width:100%;min-height:170px;border:1.5px solid #E8E4D8;border-radius:14px;padding:14px;font-size:15px;resize:vertical;background:#FBFCFA;color:var(--ink)}\ntextarea:focus{outline:none;border-color:var(--sage)}\n\n.row{display:flex;gap:12px;flex-wrap:wrap}\n.field{flex:1;min-width:180px}\n.field label{display:block;font-size:13px;font-weight:700;color:#6d7a6e;margin-bottom:6px}\n.field input,.field select{width:100%;padding:11px 12px;border:1.5px solid #E8E4D8;border-radius:12px;font-size:14px;background:#FBFCFA;color:var(--ink)}\n.field input:focus,.field select:focus{outline:none;border-color:var(--sage)}\n\n.go{width:100%;padding:17px;border:none;border-radius:16px;background:linear-gradient(135deg,var(--sage),var(--sage-dark));color:#fff;font-size:19px;font-weight:900;cursor:pointer;box-shadow:0 6px 18px rgba(92,127,96,.35);transition:.2s;margin-top:4px}\n.go:hover{transform:translateY(-2px);box-shadow:0 9px 24px rgba(92,127,96,.45)}\n.go:disabled{opacity:.55;cursor:not-allowed;transform:none}\n\n.loading{text-align:center;padding:36px 10px;display:none}\n.loading.show{display:block}\n.spin{width:52px;height:52px;border:5px solid #E4EBE4;border-top-color:var(--sage);border-radius:50%;margin:0 auto 16px;animation:sp 1s linear infinite}\n@keyframes sp{to{transform:rotate(360deg)}}\n.loading .step{font-weight:700;color:var(--sage-dark);font-size:15px;min-height:22px}\n.err{display:none;background:#FBEEEC;border:1.5px solid #E7BBB3;color:#9C4536;border-radius:12px;padding:14px;font-size:14px;font-weight:500;margin-top:12px}\n.err.show{display:block}\n\n/* ===== معاينة الأسئلة ===== */\n.preview{display:none}\n.preview.show{display:block}\n.q-item{background:#FBFCFA;border:1.5px solid #E8E4D8;border-radius:12px;padding:14px;margin-bottom:10px}\n.q-item .qt{font-weight:800;font-size:14px;margin-bottom:6px}\n.q-item .lvl{display:inline-block;font-size:11px;background:#EFE7D2;color:#8a6d1f;border-radius:8px;padding:2px 8px;font-weight:700;margin-right:6px}\n.q-item .ans{font-size:13px;color:var(--sage-dark);font-weight:700}\n.play-btn{width:100%;padding:16px;border:none;border-radius:16px;background:linear-gradient(135deg,var(--gold),#B0913B);color:#fff;font-size:18px;font-weight:900;cursor:pointer;box-shadow:0 6px 18px rgba(201,168,76,.4);margin-top:8px}\n.regen{width:100%;padding:12px;border:1.5px solid #E8E4D8;border-radius:14px;background:#fff;color:#6d7a6e;font-weight:700;font-size:14px;cursor:pointer;margin-top:10px}\n\n/* ===== اللعبة ===== */\n#game{display:none;position:fixed;inset:0;z-index:100;overflow-y:auto;color:#fff;\n  background:\n    radial-gradient(circle 90px at 12% 18%,rgba(90,160,255,.20),transparent 70%),\n    radial-gradient(circle 60px at 88% 12%,rgba(140,190,255,.22),transparent 70%),\n    radial-gradient(circle 110px at 78% 42%,rgba(70,120,255,.16),transparent 70%),\n    radial-gradient(circle 70px at 8% 55%,rgba(120,180,255,.16),transparent 70%),\n    radial-gradient(circle 50px at 45% 15%,rgba(160,210,255,.14),transparent 70%),\n    radial-gradient(circle 80px at 60% 80%,rgba(80,130,255,.12),transparent 70%),\n    radial-gradient(ellipse 90% 55% at 50% -8%,#3A5BD9 0%,#1B2E7E 38%,#0B1550 68%,#050B2E 100%)}\n/* أعمدة إضاءة المسرح المتحركة */\n#game::before{content:'';position:fixed;inset:0;pointer-events:none;opacity:.8;\n  background:\n    conic-gradient(from 168deg at 18% -12%,transparent 0 47%,rgba(110,150,255,.22) 50%,transparent 53% 100%),\n    conic-gradient(from 192deg at 82% -12%,transparent 0 47%,rgba(110,150,255,.22) 50%,transparent 53% 100%),\n    conic-gradient(from 178deg at 42% -15%,transparent 0 48%,rgba(160,190,255,.16) 50%,transparent 52% 100%),\n    conic-gradient(from 182deg at 58% -15%,transparent 0 48%,rgba(160,190,255,.16) 50%,transparent 52% 100%);\n  animation:sweep 9s ease-in-out infinite alternate}\n@keyframes sweep{from{transform:translateX(-3%) }to{transform:translateX(3%)}}\n/* أرضية المسرح بمنظور + نقاط الجمهور */\n#game::after{content:'';position:fixed;left:0;right:0;bottom:0;height:38vh;pointer-events:none;\n  background:\n    radial-gradient(2px 2px at 12% 22%,rgba(255,225,140,.8),transparent 60%),\n    radial-gradient(2px 2px at 28% 48%,rgba(255,255,255,.5),transparent 60%),\n    radial-gradient(2px 2px at 44% 30%,rgba(255,225,140,.6),transparent 60%),\n    radial-gradient(2px 2px at 61% 52%,rgba(255,255,255,.45),transparent 60%),\n    radial-gradient(2px 2px at 75% 28%,rgba(255,225,140,.7),transparent 60%),\n    radial-gradient(2px 2px at 90% 45%,rgba(255,255,255,.5),transparent 60%),\n    radial-gradient(2px 2px at 8% 68%,rgba(255,225,140,.5),transparent 60%),\n    radial-gradient(2px 2px at 52% 75%,rgba(255,255,255,.4),transparent 60%),\n    radial-gradient(2px 2px at 83% 70%,rgba(255,225,140,.55),transparent 60%),\n    repeating-linear-gradient(90deg,transparent 0 46px,rgba(90,130,255,.10) 46px 48px),\n    linear-gradient(180deg,transparent 0%,rgba(20,35,110,.55) 40%,rgba(8,15,55,.9) 100%)}\n#game.show{display:block}\n.g-inner{max-width:900px;margin:0 auto;padding:22px 16px 50px;min-height:100vh;display:flex;flex-direction:column;position:relative}\n.g-close{position:absolute;top:10px;left:10px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);color:#fff;width:36px;height:36px;border-radius:50%;font-size:16px;cursor:pointer;z-index:5}\n\n/* سداسيات ثلاثية الأبعاد */\n.hex{clip-path:polygon(26px 0,calc(100% - 26px) 0,100% 50%,calc(100% - 26px) 100%,26px 100%,0 50%)}\n.hexline{position:relative;background:linear-gradient(180deg,#FFE9A3 0%,#F3C64B 28%,#B8860B 62%,#8A6508 100%);padding:3px;\n  filter:drop-shadow(0 7px 10px rgba(0,0,0,.5)) drop-shadow(0 0 12px rgba(243,198,75,.3))}\n.hexline>.hexin{background:linear-gradient(180deg,#25379E 0%,#131F6B 45%,#0A123F 100%);position:relative}\n.hexline>.hexin::before{content:'';position:absolute;left:8%;right:8%;top:0;height:46%;pointer-events:none;\n  background:linear-gradient(180deg,rgba(255,255,255,.22),transparent);border-radius:0 0 50% 50%}\n\n.q-box{margin-bottom:18px;position:relative}\n.q-label{display:flex;justify-content:center;margin-bottom:-14px;position:relative;z-index:2}\n.q-label span{background:linear-gradient(180deg,#FFE9A3,#F3C64B 45%,#B8860B);color:#2A1E00;font-weight:900;font-size:14px;padding:7px 26px;clip-path:polygon(14px 0,calc(100% - 14px) 0,100% 50%,calc(100% - 14px) 100%,14px 100%,0 50%);box-shadow:0 3px 8px rgba(0,0,0,.4)}\n.q-box .hexin{padding:26px 40px 20px;font-size:19px;font-weight:800;text-align:center;line-height:1.8;text-shadow:0 2px 4px rgba(0,0,0,.5)}\n.opts{display:grid;grid-template-columns:1fr 1fr;gap:14px 22px;perspective:800px;padding-right:14px}\n@media(max-width:560px){.opts{grid-template-columns:1fr}}\n.opt{border:none;background:none;padding:0;cursor:pointer;text-align:right;transition:transform .15s;position:relative}\n.opt .hexin{display:flex;align-items:center;padding:14px 40px 14px 20px;font-size:16px;font-weight:800;color:#fff;transition:.15s;text-shadow:0 2px 3px rgba(0,0,0,.55);justify-content:space-between;gap:8px}\n.opt .n{position:absolute;right:-13px;top:50%;transform:translateY(-50%);z-index:3;\n  width:40px;height:40px;background:linear-gradient(180deg,#FFE9A3,#F3C64B 45%,#C68A10);color:#2A1E00;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:17px;\n  clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%);\n  filter:drop-shadow(0 3px 4px rgba(0,0,0,.45));text-shadow:none}\n.opt .oi{font-size:20px;flex-shrink:0}\n.opt:hover:not(:disabled){transform:translateY(-3px) scale(1.015)}\n.opt:hover:not(:disabled) .hexin{background:linear-gradient(180deg,#2F44BE 0%,#1A2A88 45%,#101B5E 100%)}\n.opt:active:not(:disabled){transform:translateY(1px) scale(.99)}\n.opt:disabled{cursor:default}\n\n/* الشعار */\n.g-logo{border-radius:50%;position:relative;\n  background:\n    repeating-conic-gradient(from 0deg,rgba(150,190,255,.28) 0 4deg,transparent 4deg 12deg),\n    radial-gradient(circle at 50% 42%,#3B5AE0 0%,#16247E 55%,#0A1250 100%);\n  border:4px solid #D9A21B;outline:2.5px solid #F8DE8B;outline-offset:-9px;\n  box-shadow:0 0 34px rgba(243,198,75,.6),inset 0 0 26px rgba(60,100,230,.6);\n  display:flex;align-items:center;justify-content:center;text-align:center}\n.g-logo b{font-size:17px;font-weight:900;color:#fff;text-shadow:0 0 12px rgba(243,198,75,.9),0 2px 3px rgba(0,0,0,.6);line-height:1.4}\n.g-logo b span{display:block;font-size:24px;color:var(--game-gold)}\n.g-start .g-logo{width:130px;height:130px;margin:0 auto 14px}\n.ladder-col{display:flex;flex-direction:column}\n@media(max-width:700px){.ladder-col{order:-1;flex-direction:row;align-items:center;gap:12px}.ladder-col .ladder{flex:1}}\n\n.g-start{text-align:center;margin:auto 0;padding:30px 0}\n.g-title{display:inline-block;margin-bottom:6px}\n.g-title .hexin{padding:12px 44px;font-size:26px;font-weight:900;color:var(--game-gold);text-shadow:0 0 16px rgba(243,198,75,.5)}\n.g-start h2{font-size:15px;font-weight:700;color:#B9C4EF;margin:12px 0 24px}\n.g-start input{width:min(320px,90%);padding:13px;border-radius:14px;border:2px solid rgba(243,198,75,.55);background:rgba(255,255,255,.08);color:#fff;font-size:16px;text-align:center;margin-bottom:22px}\n.g-start input::placeholder{color:#8FA0D8}\n.g-startbtn{display:block;margin:0 auto;padding:15px 52px;border:none;border-radius:50px;background:linear-gradient(135deg,var(--game-gold),#D9A21B);color:#3A2A00;font-size:20px;font-weight:900;cursor:pointer;box-shadow:0 0 30px rgba(243,198,75,.5);animation:pulse 1.8s infinite}\n@keyframes pulse{50%{box-shadow:0 0 46px rgba(243,198,75,.85)}}\n.g-brand{margin-top:auto;text-align:center;color:#7286C9;font-size:12px;padding-top:24px}\n\n/* تخطيط اللعب: أسئلة + سلم المبالغ */\n.play-grid{display:grid;grid-template-columns:1fr 210px;gap:18px;align-items:start}\n@media(max-width:700px){.play-grid{grid-template-columns:1fr}}\n.hud{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px;flex-wrap:wrap}\n.hud .pill{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);border-radius:30px;padding:7px 16px;font-weight:800;font-size:14px}\n#timer{border-color:rgba(243,198,75,.45)}\n#timer.hot{color:#FF7B6B;animation:blink .5s infinite}\n@keyframes blink{50%{opacity:.4}}\n.prog{height:8px;background:rgba(255,255,255,.12);border-radius:10px;overflow:hidden;margin-bottom:18px}\n.prog i{display:block;height:100%;background:linear-gradient(90deg,var(--game-gold),#F8DE8B);border-radius:10px;transition:width .5s}\n\n.q-box{margin-bottom:18px}\n.opt.correct .hexin{background:linear-gradient(180deg,#1F7A45,#125230)!important;box-shadow:inset 0 0 18px rgba(75,217,138,.4)}\n.opt.correct .hexline{background:linear-gradient(135deg,#4BD98A,#1F7A45)}\n.opt.wrong .hexin{background:linear-gradient(180deg,#8C2B25,#5E1B17)!important}\n.opt.wrong{animation:shake .4s}\n@keyframes shake{25%{transform:translateX(6px)}75%{transform:translateX(-6px)}}\n.opt.dim{opacity:.25;pointer-events:none}\n\n/* سلم المبالغ */\n.ladder{background:linear-gradient(180deg,#0E1A5E,#081040);border:2.5px solid #D9A21B;border-radius:16px;padding:0 0 12px;box-shadow:0 0 22px rgba(243,198,75,.3);overflow:hidden}\n.ladder h3{text-align:center;font-size:15px;font-weight:900;color:#2A1E00;background:linear-gradient(180deg,#FFE9A3,#F3C64B 50%,#C68A10);padding:9px;margin-bottom:8px}\n.lrow{display:flex;align-items:center;gap:8px;padding:4px 12px;font-size:13.5px;font-weight:800;color:#E7EBFA}\n.lrow .li{color:var(--game-gold);width:20px;text-align:center}\n.lrow .lp{flex:1}\n.lrow .lc{font-size:12px}\n.lrow.won{color:#F8DE8B}\n.lrow.cur{background:linear-gradient(90deg,#F08A1D,#D96E0A);color:#fff;box-shadow:0 0 14px rgba(240,138,29,.65);margin:0 5px;border-radius:8px;padding:4px 7px}\n.ladder .helps{display:flex;gap:8px;justify-content:center;margin-top:10px;padding-top:10px;border-top:1.5px solid rgba(243,198,75,.4)}\n.ladder .help{width:44px;height:44px;padding:0;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px}\n.helps{display:flex;gap:10px;justify-content:center;margin-top:16px}\n.help{background:rgba(255,255,255,.1);border:2px solid #D9A21B;color:#fff;border-radius:30px;padding:9px 16px;font-weight:800;font-size:13px;cursor:pointer;box-shadow:0 0 10px rgba(243,198,75,.3)}\n.help:disabled{opacity:.3;cursor:not-allowed;box-shadow:none}\n\n.fb{display:none;background:rgba(10,18,63,.92);border:2px solid rgba(243,198,75,.5);border-radius:18px;padding:20px;margin-top:18px;text-align:center}\n.fb.show{display:block}\n.fb .h{font-size:20px;font-weight:900;margin-bottom:8px}\n.fb .h.ok{color:#4BD98A}.fb .h.no{color:#FF7B6B}\n.fb .ex{font-size:15px;color:#D5DCF5;line-height:1.8}\n.fb button{margin-top:14px;padding:12px 40px;border:none;border-radius:40px;background:var(--game-gold);color:#3A2A00;font-weight:900;font-size:16px;cursor:pointer}\n.g-end{text-align:center;margin:auto 0;padding:30px 0}\n.g-end .medal{font-size:70px}\n.g-end h1{font-size:26px;font-weight:900;color:var(--game-gold);margin:10px 0}\n.g-end .stats{display:flex;justify-content:center;gap:14px;flex-wrap:wrap;margin:20px 0}\n.g-end .st{background:rgba(255,255,255,.08);border:1.5px solid rgba(243,198,75,.4);border-radius:14px;padding:14px 22px;min-width:110px}\n.g-end .st b{display:block;font-size:24px;color:var(--game-gold)}\n.g-end .st span{font-size:13px;color:#B9C4EF}\n.confetti{position:fixed;top:-10px;width:10px;height:14px;z-index:200;pointer-events:none;animation:fall linear forwards}\n@keyframes fall{to{transform:translateY(105vh) rotate(600deg)}}\n\n/* ===== وضع كتابة الأسئلة يدويًا ===== */\n.man-note{background:#FBF3DD;border:1.5px solid #EADFB8;color:#8a6d1f;font-size:13px;font-weight:700;padding:10px 12px;border-radius:12px;margin-bottom:12px;line-height:1.7}\n.man-form{display:flex;flex-direction:column;gap:9px}\n.man-in{width:100%;padding:11px 13px;border:1.5px solid #E8E4D8;border-radius:12px;font-size:14px;background:#FBFCFA;color:#2E3A2F}\n.man-in:focus{outline:none;border-color:#7A9E7E}\n.man-opt{display:flex;align-items:center;gap:9px}\n.man-opt input[type=radio]{width:22px;height:22px;flex-shrink:0;accent-color:#5C7F60;cursor:pointer}\n.man-opt .man-in{flex:1}\n.man-hint{font-size:12.5px;color:#a5aea0}\n.man-add{background:#F0F5F0;border:1.5px solid #DDE8DD;color:#5C7F60;font-weight:800;font-size:14px;padding:12px;border-radius:12px;cursor:pointer;transition:.18s}\n.man-add:hover{background:#E7F0E8}\n.man-list{margin-top:12px;display:flex;flex-direction:column;gap:8px}\n.man-q{background:#FBFCFA;border:1.5px solid #E8E4D8;border-radius:12px;padding:10px 12px;display:flex;gap:8px;align-items:flex-start}\n.man-q .mqt{flex:1;font-size:13.5px;font-weight:700;color:#2E3A2F}\n.man-q .mqa{font-size:12.5px;color:#5C7F60;font-weight:700;margin-top:3px}\n.man-q .mdel{background:none;border:none;color:#c9908a;font-size:15px;cursor:pointer;flex-shrink:0}\n.man-use{width:100%;padding:15px;border:none;border-radius:14px;background:linear-gradient(135deg,#F3C64B,#B0913B);color:#fff;font-size:16px;font-weight:900;cursor:pointer;margin-top:12px}\n\n.free-banner{display:none;margin-top:10px;background:linear-gradient(180deg,#FFF3D0,#FBE3A6);color:#7A5A12;\n  font-weight:900;font-size:14px;padding:10px 18px;border-radius:16px;border:1.6px solid #EAD08A;\n  box-shadow:0 4px 12px rgba(217,162,22,.22);animation:fbpop .5s ease}\n@keyframes fbpop{from{transform:scale(.9);opacity:0}to{transform:scale(1);opacity:1}}\n\n/* ===== شارة الرصيد + الشراء ===== */\n.cbadge{display:inline-block;margin-top:10px;background:#EAF3EC;color:#3E6B45;font-weight:800;font-size:13px;padding:6px 16px;border-radius:20px;border:1.5px solid #CFE3D2}\n.cbadge.empty{background:#FBEEEC;color:#9C4536;border-color:#E7BBB3}\n.cbadge.admin{background:#FBF3DD;color:#8a6d1f;border-color:#EADFB8}\n.buy-link{display:block;margin:10px auto 0;background:none;border:none;color:#5C7F60;font-weight:800;font-size:13px;cursor:pointer;text-decoration:underline}\n.buy-ov{position:fixed;inset:0;z-index:300;background:rgba(20,30,25,.55);backdrop-filter:blur(3px);display:none;align-items:center;justify-content:center;padding:20px}\n.buy-ov.show{display:flex}\n.buy-card{background:#fff;border-radius:22px;max-width:400px;width:100%;padding:28px 24px;text-align:center;position:relative;box-shadow:0 20px 60px rgba(0,0,0,.3);animation:pop .25s ease}\n@keyframes pop{from{transform:scale(.9);opacity:0}to{transform:scale(1);opacity:1}}\n.buy-x{position:absolute;top:14px;left:14px;background:#F0F1EC;border:none;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:13px;color:#6d7a6e}\n.buy-seed{font-size:40px}\n.buy-card h3{font-size:20px;font-weight:900;color:var(--sage-dark);margin:6px 0 8px}\n.buy-card p{color:#7d8a7e;font-size:14px;line-height:1.7}\n.buy-opts{display:flex;gap:12px;margin:18px 0 6px}\n.buy-opt{flex:1;position:relative;background:#FBFCFA;border:2px solid #E8E4D8;border-radius:16px;padding:16px 10px;cursor:pointer;transition:.18s;display:flex;flex-direction:column;align-items:center;gap:3px}\n.buy-opt:hover{border-color:var(--sage);transform:translateY(-2px)}\n.buy-opt b{font-size:15px;color:var(--ink);font-weight:800}\n.buy-opt .pr{font-size:19px;font-weight:900;color:var(--sage-dark)}\n.buy-opt small{font-size:11px;color:#a5aea0}\n.buy-opt.best{border-color:var(--gold);background:#FFFDF6}\n.buy-opt.best .tag{position:absolute;top:-11px;right:50%;transform:translateX(50%);background:var(--gold);color:#fff;font-size:10px;font-weight:800;padding:2px 10px;border-radius:20px;white-space:nowrap}\n.buy-note{font-size:12px;color:#a5aea0;margin-top:14px}\n\n.q-box .hexin{ font-size:28px !important; padding:32px 48px 26px !important; line-height:1.75 !important; }\n.q-label span{ font-size:17px !important; padding:8px 30px !important; }\n/* بطاقات الإجابات: بار كامل بعرض ثابت (block) عشان تبين واضحة في كل المتصفحات */\n.opt{ display:block !important; }\n.opt .hexline{ display:block !important; width:100% !important; }\n.opt .hexin{ display:flex !important; align-items:center !important; min-height:64px !important; font-size:23px !important; padding:20px 52px 20px 22px !important; }\n.opt .n{ width:48px !important; height:48px !important; font-size:22px !important; right:-15px !important; }\n.opt .oi{ font-size:24px !important; }\n@media(max-width:560px){\n  .q-box .hexin{ font-size:22px !important; padding:24px 30px 20px !important; }\n  .opt .hexin{ font-size:20px !important; min-height:56px !important; padding:16px 44px 16px 18px !important; }\n  .opt .n{ width:42px !important; height:42px !important; font-size:19px !important; }\n}\n\n/* الأعمدة الضوئية تتمايل بوضوح */\n#game::before{ animation:mfxsweep 8s ease-in-out infinite alternate !important; }\n@keyframes mfxsweep{ from{transform:translateX(-4%) rotate(-1.3deg)} to{transform:translateX(4%) rotate(1.3deg)} }\n/* طبقة خلفية متحركة: أشعة تدور + جسيمات ذهبية تطفو */\n.mfx{ position:fixed; inset:0; pointer-events:none; z-index:0; overflow:hidden; }\n.mfx::before{ content:''; position:absolute; left:50%; top:50%; width:230vmax; height:230vmax; margin-left:-115vmax; margin-top:-115vmax;\n  background:repeating-conic-gradient(from 0deg, rgba(130,170,255,.06) 0deg 5deg, transparent 5deg 13deg);\n  animation:mfxspin 70s linear infinite; }\n@keyframes mfxspin{ to{ transform:rotate(360deg) } }\n.mfx::after{ content:''; position:absolute; inset:0; opacity:.9;\n  background-image:\n    radial-gradient(1.6px 1.6px at 20px 30px, rgba(255,225,140,.75), transparent 60%),\n    radial-gradient(1.4px 1.4px at 80px 90px, rgba(255,255,255,.5), transparent 60%),\n    radial-gradient(1.8px 1.8px at 150px 50px, rgba(255,225,140,.6), transparent 60%);\n  background-size:180px 200px, 260px 300px, 340px 380px;\n  animation:mfxdrift 26s linear infinite; }\n@keyframes mfxdrift{ to{ background-position:0 -800px, 0 -1200px, 0 -1600px } }\n/* المحتوى فوق الخلفية دائمًا */\n.g-inner{ z-index:1; }\n/* احترام تفضيل تقليل الحركة */\n@media(prefers-reduced-motion:reduce){ #game::before,.mfx::before,.mfx::after{ animation:none !important } }\n\n/* ملء الشاشة عموديًا: توسيط منطقة اللعب (السؤال + الخيارات + قائمة المبالغ) فيختفي الفراغ السفلي */\n.play-grid{ flex:1 1 auto !important; align-items:center !important; align-content:center !important; }\n.opts{ gap:22px 28px !important; }\n.q-box{ margin-bottom:24px !important; }\n.ladder-col{ justify-content:center !important; }\n@media(max-width:700px){ .play-grid{ align-content:start !important; } }\n\n/* ملء الشاشة عرضًا (كان محصورًا 900px) */\n.g-inner{ max-width:1650px !important; width:96vw !important; padding:18px 30px 28px !important; }\n.play-grid{ grid-template-columns:1fr 270px !important; gap:16px 30px !important; }\n/* شريط العنوان العلوي مثل الصورة */\n.q-header{ text-align:center; margin-bottom:12px; }\n.q-title{ display:inline-block; background:linear-gradient(180deg,#25379E,#131F6B); border:2.5px solid #D9A21B; border-radius:14px; padding:11px 46px; box-shadow:0 0 22px rgba(243,198,75,.3); }\n.q-title span{ font-size:27px; font-weight:900; color:var(--game-gold); text-shadow:0 0 14px rgba(243,198,75,.45); }\n.q-sub2{ margin-top:8px; font-size:15px; font-weight:800; color:#CBD6FF; letter-spacing:.5px; }\n@media(max-width:700px){\n  .g-inner{ width:100vw !important; padding:12px 12px 22px !important; }\n  .play-grid{ grid-template-columns:1fr !important; }\n  .q-title span{ font-size:20px }\n  .q-title{ padding:9px 26px }\n}\n\n.mg-home{ display:inline-flex; align-items:center; gap:6px; color:var(--sage-dark); font-weight:800; font-size:13.5px; text-decoration:none; background:#F0F5F0; border:1.5px solid #DDE8DD; border-radius:12px; padding:9px 16px; margin-bottom:16px; transition:.18s; }\n.mg-home:hover{ background:#E7F0E8; border-color:var(--sage); }\n.g-home{ position:absolute; top:10px; right:10px; background:rgba(255,255,255,.12); border:1px solid rgba(255,255,255,.2); color:#fff; width:38px; height:38px; border-radius:50%; font-size:17px; display:flex; align-items:center; justify-content:center; z-index:6; text-decoration:none; transition:.18s; }\n.g-home:hover{ background:rgba(255,255,255,.24); }\n\n/* ===== صيد البالون — طبقة اللعبة ===== */\n#bstage{position:absolute;inset:0;touch-action:none;background:#0d1b2a}\n#bcv{position:absolute;inset:0;width:100%;height:100%;display:block}\n#bhud{position:absolute;inset:0;pointer-events:none;display:flex;flex-direction:column;align-items:center;padding:14px}\n#bqbar{pointer-events:none;background:rgba(255,255,255,.92);backdrop-filter:blur(8px);\n  border-radius:22px;padding:12px 26px;box-shadow:0 10px 30px rgba(23,60,90,.18);\n  font-size:clamp(17px,3.4vw,26px);font-weight:800;color:#1c3d5a;text-align:center;\n  max-width:min(680px,92vw)}\n#bqbar small{display:block;font-size:.62em;font-weight:500;color:#7fa0b8;margin-top:2px}\n#btop{display:flex;gap:10px;align-items:center;width:100%;max-width:min(680px,92vw);\n  justify-content:space-between;margin-bottom:10px}\n.bpill{background:rgba(255,255,255,.9);border-radius:999px;padding:7px 16px;font-weight:800;\n  color:#1c3d5a;font-size:clamp(14px,2.6vw,18px);box-shadow:0 6px 18px rgba(23,60,90,.14)}\n#bhearts{letter-spacing:3px;font-size:clamp(15px,3vw,20px)}\n#bflash{position:absolute;top:38%;left:50%;transform:translate(-50%,-50%) scale(.6);\n  font-size:clamp(30px,8vw,64px);font-weight:800;opacity:0;pointer-events:none;\n  text-shadow:0 6px 0 rgba(0,0,0,.12)}\n#bflash.go{animation:bpop 1s ease-out forwards}\n@keyframes bpop{0%{opacity:0;transform:translate(-50%,-50%) scale(.5)}\n  25%{opacity:1;transform:translate(-50%,-50%) scale(1.12)}\n  70%{opacity:1;transform:translate(-50%,-50%) scale(1)}\n  100%{opacity:0;transform:translate(-50%,-58%) scale(1)}}\n.bscreen{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;\n  justify-content:center;gap:18px;text-align:center;padding:24px;\n  background:radial-gradient(120% 100% at 50% 0%,rgba(255,247,232,.96),rgba(255,224,196,.96));z-index:5}\n.bscreen.hide{display:none}\n.bscreen h1{font-size:clamp(30px,7vw,56px);color:#e07a2f;font-weight:800;line-height:1.15}\n.bscreen p{font-size:clamp(15px,3.2vw,20px);color:#8a5a33;max-width:34ch;line-height:1.7}\n.bbtn{pointer-events:auto;border:none;cursor:pointer;font-family:inherit;font-weight:800;\n  font-size:clamp(18px,3.6vw,24px);color:#fff;padding:15px 46px;border-radius:999px;\n  background:linear-gradient(180deg,#ffa63d,#f2792a);box-shadow:0 8px 0 #cf5f1c,0 16px 28px rgba(207,95,28,.35);\n  transition:transform .12s,box-shadow .12s}\n.bbtn:active{transform:translateY(5px);box-shadow:0 3px 0 #cf5f1c,0 8px 16px rgba(207,95,28,.3)}\n.blogo{font-size:clamp(52px,13vw,96px);line-height:1}\n#bscoreBig{font-size:clamp(40px,10vw,76px);font-weight:800;color:#e07a2f}\n.bbrand{position:absolute;bottom:8px;left:0;right:0;text-align:center;color:rgba(255,255,255,.55);\n  font-size:12px;font-weight:700;pointer-events:none;z-index:4}\n";
const GAME_BODY = "<!-- ============ المولّد ============ -->\n<div class=\"gen-wrap\" id=\"genWrap\">\n  <a href=\"/\" class=\"mg-home\">← رجوع لمنصة غراس</a>\n  <div class=\"brand\">\n    <div class=\"seed\">🌱</div>\n    <h1>صيد البالون 🎈</h1>\n    <p>ارفع الدرس… والذكاء يبني الأسئلة، وطلابك يفرقعون البالونات</p>\n    <span class=\"badge\">أداة غراس المعلم</span>\n    <div id=\"creditBadge\" class=\"cbadge\"></div>\n    <button class=\"buy-link\" onclick=\"showBuy()\">＋ شراء ألعاب</button>\n  </div>\n\n  <div class=\"card\">\n    <h2><span class=\"num\">١</span> محتوى الدرس</h2>\n    <div class=\"tabs\">\n      <button class=\"tab on\" id=\"tabImg\" onclick=\"switchTab('img')\">📷 صور الدرس</button>\n      <button class=\"tab\" id=\"tabTxt\" onclick=\"switchTab('txt')\">📝 نص الدرس</button>\n      <button class=\"tab\" id=\"tabMan\" onclick=\"switchTab('man')\">✍️ اكتب أسئلتك</button>\n    </div>\n    <div id=\"paneImg\">\n      <label class=\"drop\" id=\"drop\" for=\"fileInput\" style=\"display:block\">\n        <div class=\"ic\">📄</div>\n        <p>اضغط هنا لرفع صور صفحات الدرس</p>\n        <small>أو صوّرها بالكاميرا مباشرة — حتى ٥ صور</small>\n      </label>\n      <input type=\"file\" id=\"fileInput\" accept=\"image/*\" multiple>\n      <div class=\"thumbs\" id=\"thumbs\"></div>\n    </div>\n    <div id=\"paneTxt\" style=\"display:none\">\n      <textarea id=\"lessonText\" placeholder=\"الصق نص الدرس هنا…\"></textarea>\n    </div>\n    <div id=\"paneMan\" style=\"display:none\">\n      <div class=\"man-note\">✍️ اكتب أسئلتك كما تريد — تُستخدم <b>حرفيًا بدون أي تعديل</b> من الذكاء.</div>\n      <div class=\"man-form\">\n        <input id=\"mq\" class=\"man-in\" placeholder=\"اكتب نص السؤال…\">\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"0\" checked title=\"الصحيحة\"><input id=\"mo0\" class=\"man-in\" placeholder=\"الخيار الأول\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"1\" title=\"الصحيحة\"><input id=\"mo1\" class=\"man-in\" placeholder=\"الخيار الثاني\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"2\" title=\"الصحيحة\"><input id=\"mo2\" class=\"man-in\" placeholder=\"الخيار الثالث\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"3\" title=\"الصحيحة\"><input id=\"mo3\" class=\"man-in\" placeholder=\"الخيار الرابع\"></div>\n        <div class=\"man-hint\">حدّد الدائرة أمام الإجابة الصحيحة 👆 ثم أضف السؤال</div>\n        <button class=\"man-add\" onclick=\"addManualQ()\">➕ أضف السؤال</button>\n      </div>\n      <div id=\"manList\" class=\"man-list\"></div>\n      <button class=\"man-use\" id=\"manUseBtn\" onclick=\"useManual()\" style=\"display:none\">▶️ استخدم أسئلتي</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2><span class=\"num\">٢</span> إعدادات اللعبة</h2>\n    <div class=\"row\">\n      <div class=\"field\">\n        <label>اسم الدرس (اختياري)</label>\n        <input id=\"lessonName\" placeholder=\"مثال: غزوة بدر\">\n      </div>\n      <div class=\"field\">\n        <label>الصف</label>\n        <select id=\"gradeSel\">\n          <option value=\"الأول\">الأول</option><option value=\"الثاني\">الثاني</option>\n          <option value=\"الثالث\">الثالث</option><option value=\"الرابع\">الرابع</option>\n          <option value=\"الخامس\" selected>الخامس</option><option value=\"السادس\">السادس</option>\n          <option value=\"السابع\">السابع</option><option value=\"الثامن\">الثامن</option><option value=\"التاسع\">التاسع</option>\n        </select>\n      </div>\n      <div class=\"field\">\n        <label>الفئة</label>\n        <select id=\"genderSel\">\n          <option value=\"بنات\" selected>بنات</option>\n          <option value=\"بنين\">بنين</option>\n        </select>\n      </div>\n    </div>\n  </div>\n\n  <button class=\"go\" id=\"goBtn\" onclick=\"generate()\">✨ إنشاء اللعبة</button>\n\n  <div class=\"loading\" id=\"loading\">\n    <div class=\"spin\"></div>\n    <div class=\"step\" id=\"stepText\">جارٍ قراءة الدرس…</div>\n  </div>\n  <div class=\"err\" id=\"errBox\"></div>\n\n  <div class=\"card preview\" id=\"preview\">\n    <h2><span class=\"num\">٣</span> الأسئلة المولّدة <span id=\"qCount\" style=\"color:#a5aea0;font-weight:500;font-size:13px\"></span></h2>\n    <div id=\"qList\"></div>\n    <button class=\"regen\" onclick=\"openGame(true)\">👀 معاينة اللعبة — بلا خصم</button>\n    <button class=\"play-btn\" onclick=\"openGame()\">🎈 تشغيل / إنشاء اللعبة</button>\n    <button class=\"regen\" onclick=\"generate()\">🔄 إعادة توليد الأسئلة</button>\n  </div>\n</div>\n\n<!-- ============ اللعبة ============ -->\n<div id=\"game\">\n  <button class=\"g-close\" onclick=\"closeGame()\">✕</button>\n  <div id=\"bstage\">\n    <canvas id=\"bcv\"></canvas>\n    <div id=\"bhud\">\n      <div id=\"btop\">\n        <div class=\"bpill\" id=\"bscore\">النقاط ٠</div>\n        <div class=\"bpill\" id=\"bhearts\">❤️❤️❤️</div>\n      <div class=\"bpill\" id=\"bprev\" style=\"display:none\">👀 معاينة تجريبية — بلا خصم وبلا حفظ</div>\n      </div>\n      <div id=\"bqbar\"><span id=\"bqtext\">…</span><small>اسحب المقلاع للخلف ثم أفلته 🎯</small></div>\n      <div id=\"bflash\"></div>\n    </div>\n    <div class=\"bscreen\" id=\"bstart\">\n      <div class=\"blogo\">🎈</div>\n      <h1>صيد البالون</h1>\n      <p>اقرأ السؤال، صوّب على البالون الصحيح، واسحب المقلاع للخلف ثم أفلته!</p>\n      <button class=\"bbtn\" onclick=\"startPlay()\">ابدأ اللعب</button>\n    </div>\n    <div class=\"bscreen hide\" id=\"bend\">\n      <div class=\"blogo\" id=\"bendEmoji\">🏆</div>\n      <h1 id=\"bendTitle\">أحسنت!</h1>\n      <div id=\"bscoreBig\">٠</div>\n      <p id=\"bendMsg\"></p>\n      <button class=\"bbtn\" onclick=\"startPlay()\">العب مرة أخرى</button>\n    </div>\n    <div class=\"bbrand\">🌱 غراس المعلم — جميع الحقوق محفوظة</div>\n  </div>\n</div>\n";
const GAME_JS = "/* ---------- الحالة ---------- */\nlet images=[], questions=[];\nlet COMMITTED=false, DEMO=false;\nconst IS_ADMIN=!!(window.__IS_ADMIN);\nlet CREDITS=(typeof window.__GAME_CREDITS==='number')?window.__GAME_CREDITS:0;\nconst AR=n=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n/* ⚠️ نص السؤال والخيارات محتوى خارجي (معلمة/ذكاء) — كل عرضٍ له في HTML يمرّ من هنا،\n   والشريط داخل اللعبة يُكتب بـtextContent أصلًا فلا ينفَّذ منه شيء. */\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n\n/* ---------- التبويبات والصور ---------- */\nfunction switchTab(t){\n  document.getElementById('tabImg').classList.toggle('on',t==='img');\n  document.getElementById('tabTxt').classList.toggle('on',t==='txt');\n  document.getElementById('tabMan').classList.toggle('on',t==='man');\n  document.getElementById('paneImg').style.display=t==='img'?'':'none';\n  document.getElementById('paneTxt').style.display=t==='txt'?'':'none';\n  document.getElementById('paneMan').style.display=t==='man'?'':'none';\n  document.getElementById('goBtn').style.display=t==='man'?'none':'';\n}\ndocument.getElementById('fileInput').addEventListener('change',e=>addFiles(e.target.files));\nconst drop=document.getElementById('drop');\ndrop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('over')});\ndrop.addEventListener('dragleave',()=>drop.classList.remove('over'));\ndrop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('over');addFiles(e.dataTransfer.files)});\n\nfunction addFiles(files){\n  [...files].slice(0,5-images.length).forEach(f=>{\n    if(!f.type.startsWith('image/'))return;\n    const r=new FileReader();\n    r.onerror=()=>showErr('تعذّرت قراءة الصورة — جرّب صورة ثانية');\n    r.onload=()=>{\n      const img=new Image();\n      img.onload=()=>{\n        try{\n          const MAX=900;\n          let w=img.width,h=img.height;\n          if(Math.max(w,h)>MAX){const s=MAX/Math.max(w,h);w=Math.round(w*s);h=Math.round(h*s)}\n          const cv=document.createElement('canvas');cv.width=w;cv.height=h;\n          cv.getContext('2d').drawImage(img,0,0,w,h);\n          const url=cv.toDataURL('image/jpeg',0.65);\n          images.push({data:url.split(',')[1],type:'image/jpeg',url});\n        }catch(e){\n          images.push({data:r.result.split(',')[1],type:f.type,url:r.result});\n        }\n        renderThumbs();\n      };\n      img.onerror=()=>{\n        images.push({data:r.result.split(',')[1],type:f.type,url:r.result});\n        renderThumbs();\n      };\n      img.src=r.result;\n    };\n    r.readAsDataURL(f);\n  });\n  document.getElementById('fileInput').value='';\n}\nfunction renderThumbs(){\n  document.getElementById('thumbs').innerHTML=images.map((im,i)=>\n    `<div class=\"thumb\"><img src=\"${im.url}\"><button class=\"x\" onclick=\"images.splice(${i},1);renderThumbs()\">✕</button></div>`).join('');\n}\n\n/* ---------- التوليد ---------- */\nconst STEPS=['جارٍ قراءة صفحات الدرس… 📖','جارٍ استخراج المفاهيم والحقائق… 🔍','جارٍ بناء الأسئلة حسب مستويات بلوم… 🧠','جارٍ تجهيز اللعبة… 🎮'];\nasync function generate(){\n  DEMO=false;COMMITTED=false;MANUAL=false;\n  if(!IS_ADMIN && CREDITS<=0){ showBuy(); return; }\n  const text=document.getElementById('lessonText').value.trim();\n  if(images.length===0 && !text){showErr('ارفع صور الدرس أو الصق النص أولاً 🌱');return}\n  hideErr();\n  document.getElementById('preview').classList.remove('show');\n  document.getElementById('goBtn').disabled=true;\n  document.getElementById('loading').classList.add('show');\n  let si=0;const st=document.getElementById('stepText');st.textContent=STEPS[0];\n  const stepInt=setInterval(()=>{si=(si+1)%STEPS.length;st.textContent=STEPS[si]},3500);\n\n  const grade=document.getElementById('gradeSel').value;\n  const gender=document.getElementById('genderSel').value;\n  const lname=document.getElementById('lessonName').value.trim();\n  const genderNote=gender==='بنات'?'خاطب الطالبات بصيغة المؤنث':'خاطب الطلاب بصيغة المذكر';\n\n  const basePrompt=(part)=>`أنت خبير مناهج كويتي. أمامك محتوى درس للصف ${grade}${lname?` بعنوان \"${lname}\"`:''}.\nولّد 10 أسئلة اختيار من متعدد متدرّجة من السهل (تذكّر وفهم) إلى الصعب (تطبيق وتحليل وتقويم)، مستخرجة من محتوى الدرس فقط.\nشروط: ${genderNote}. 4 خيارات، إجابة واحدة صحيحة، مشتتات خاطئة قطعاً. الشرح سطر واحد قصير جداً. الآيات والأحاديث تُنقل بدقة.\nأجب بـ JSON مضغوط فقط بلا أسطر زائدة وبلا markdown:\n{\"lesson\":\"اسم الدرس\",\"questions\":[{\"q\":\"..\",\"options\":[\"..\",\"..\",\"..\",\"..\"],\"correct\":0,\"level\":\"تذكر\",\"explain\":\"..\"}]}\n${text?`\\nنص الدرس:\\n${text}`:''}`;\n\n  async function callAPI(part,imgSet){\n    const imgs=imgSet||images;\n    const content=[...imgs.map(im=>({type:'image',source:{type:'base64',media_type:im.type,data:im.data}})),{type:'text',text:basePrompt(part)}];\n    const body=JSON.stringify({max_tokens:2500,messages:[{role:'user',content}]});\n    const kb=Math.round(body.length/1024);\n    const res=await fetch('/api/game-ai',{\n      method:'POST',headers:{'Content-Type':'application/json'},body\n    });\n    const data=await res.json();\n    if(data.error)throw new Error((data.error.message||'خطأ في الخدمة')+` [حجم الطلب: ${kb}KB]`);\n    const raw=(data.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('\\n');\n    const clean=raw.replace(/```json|```/g,'').trim();\n    const slice=clean.slice(clean.indexOf('{'),clean.lastIndexOf('}')+1);\n    let parsed;\n    try{parsed=JSON.parse(slice)}\n    catch(_){\n      const cut=slice.lastIndexOf('},');\n      if(cut>0)parsed=JSON.parse(slice.slice(0,cut+1)+']}');\n      else throw new Error('تعذّر قراءة النتيجة');\n    }\n    return parsed;\n  }\n\n  async function tryGenerate(part){\n    try{return await callAPI(part)}\n    catch(e){\n      if(images.length>1){\n        document.getElementById('stepText').textContent='جارٍ المحاولة بصورة واحدة… 🔄';\n        return await callAPI(part,[images[0]]);\n      }\n      throw e;\n    }\n  }\n\n  try{\n    const p1=await tryGenerate(1);\n    let all=[...(p1.questions||[])];\n    let lessonTitle=p1.lesson||'';\n    // إكمال حتى 10 أسئلة (بلا تكرار) إن نقصت الدفعة الأولى\n    let tries=0;\n    while(all.length<10 && tries<3){\n      tries++;\n      try{\n        const pt=await tryGenerate(2);\n        const seen=new Set(all.map(q=>q.q));\n        (pt.questions||[]).forEach(q=>{ if(q&&q.q&&!seen.has(q.q)){ all.push(q); seen.add(q.q); } });\n        lessonTitle=lessonTitle||pt.lesson||'';\n      }catch(_){ break; }\n    }\n    questions=all.slice(0,10);\n    if(questions.length<3)throw new Error('لم يتمكن النظام من استخراج أسئلة كافية — جرّب صوراً أوضح');\n    if(lessonTitle && !lname)document.getElementById('lessonName').value=lessonTitle;\n    renderPreview();\n    try{if(window.GHLib)GHLib.save();}catch(_){}\n  }catch(e){\n    showErr('تعذّر توليد الأسئلة: '+e.message+' — جرّب مرة ثانية أو تأكد من وضوح الصور.');\n  }finally{\n    clearInterval(stepInt);\n    document.getElementById('loading').classList.remove('show');\n    document.getElementById('goBtn').disabled=false;\n  }\n}\nfunction showErr(m){const b=document.getElementById('errBox');b.textContent=m;b.classList.add('show')}\nfunction hideErr(){document.getElementById('errBox').classList.remove('show')}\n\nfunction renderPreview(){\n  document.getElementById('qCount').textContent=`(${AR(questions.length)} أسئلة)`;\n  try{saveGame();}catch(_){}\n  document.getElementById('qList').innerHTML=questions.map((q,i)=>\n    `<div class=\"q-item\"><div class=\"qt\">${AR(i+1)}. ${esc(q.q)} <span class=\"lvl\">${q.level||''}</span></div>\n     <div class=\"ans\">✔ ${q.options[q.correct]}</div></div>`).join('');\n  document.getElementById('preview').classList.add('show');\n  try{if(window.QEdit)QEdit.decorate();}catch(_){}\n  try{document.getElementById('preview').scrollIntoView({behavior:'smooth'})}catch(_){}\n}\n\n/* ---------- كتابة الأسئلة يدويًا + الحفظ التلقائي ---------- */\nlet manualQs=[], MANUAL=false;\nconst MLS_KEY='ghiras_balloons_game_v1';\nfunction addManualQ(){\n  const q=(document.getElementById('mq').value||'').trim();\n  const opts=[0,1,2,3].map(i=>(document.getElementById('mo'+i).value||'').trim());\n  if(!q){showErr('اكتب نص السؤال أولًا');return;}\n  if(opts.some(o=>!o)){showErr('اكتب الخيارات الأربعة كاملة');return;}\n  const cor=+((document.querySelector('input[name=mcorrect]:checked')||{value:'0'}).value);\n  manualQs.push({q,options:opts,correct:cor,level:'',explain:''});\n  document.getElementById('mq').value=''; [0,1,2,3].forEach(i=>document.getElementById('mo'+i).value='');\n  const r0=document.querySelector('input[name=mcorrect][value=\"0\"]'); if(r0)r0.checked=true;\n  hideErr(); renderManList();\n  /* أول سؤال صالح = الرحلة تكتمل فورًا: المعاينة تُبنى تلقائيًا فيظهر\n     زرا «معاينة» و«تشغيل / إنشاء» بلا خطوة ثانية مدفونة */\n  questions=manualQs.map(q=>({...q,options:[...q.options]}));\n  MANUAL=true; COMMITTED=false;\n  try{saveGame();}catch(_){}\n  renderPreview();\n}\nfunction delManualQ(i){ manualQs.splice(i,1); renderManList(); }\nfunction renderManList(){\n  const el=document.getElementById('manList');\n  el.innerHTML=manualQs.map((q,i)=>`<div class=\"man-q\"><div class=\"mqt\">${AR(i+1)}. ${esc(q.q)}<div class=\"mqa\">✔ ${q.options[q.correct]}</div></div><button class=\"mdel\" onclick=\"delManualQ(${i})\">✕</button></div>`).join('');\n  document.getElementById('manUseBtn').style.display=manualQs.length?'block':'none';\n}\nfunction useManual(){\n  if(manualQs.length<1){showErr('أضف سؤالًا واحدًا على الأقل');return;}\n  questions=manualQs.map(q=>({...q,options:[...q.options]}));\n  MANUAL=true; COMMITTED=false;\n  try{saveGame();}catch(_){}\n  renderPreview();\n  try{if(window.GHLib)GHLib.save();}catch(_){}\n}\n/* حفظ/استرجاع اللعبة تلقائيًا */\nfunction saveGame(){try{localStorage.setItem(MLS_KEY,JSON.stringify({questions,lesson:(document.getElementById('lessonName').value||'').trim(),committed:(typeof COMMITTED!=='undefined'&&COMMITTED),manual:(typeof MANUAL!=='undefined'&&MANUAL),ts:Date.now()}));}catch(e){}}\nfunction loadSaved(){try{const r=localStorage.getItem(MLS_KEY);if(!r)return;const d=JSON.parse(r);if(d&&Array.isArray(d.questions)&&d.questions.length){questions=d.questions;if(d.lesson)document.getElementById('lessonName').value=d.lesson;COMMITTED=!!d.committed;MANUAL=!!d.manual;renderPreview();const qc=document.getElementById('qCount');if(qc)qc.textContent=qc.textContent+' — محفوظة ✅';}}catch(e){}}\n\n/* ---------- خطافات مكتبة «ألعابي المحفوظة» (حساب المعلمة) ---------- */\nwindow.__libGetData=function(){\n  if(!questions||!questions.length)return null;\n  const lesson=(document.getElementById('lessonName').value||'').trim();\n  return { title: lesson||'صيد البالون',\n           data:{ questions, lesson, manual:(typeof MANUAL!=='undefined'&&MANUAL), committed:(typeof COMMITTED!=='undefined'&&COMMITTED) } };\n};\nwindow.__libApply=function(d){\n  if(!d||!Array.isArray(d.questions))return;\n  questions=d.questions.map(q=>({...q,options:Array.isArray(q.options)?[...q.options]:q.options}));\n  const el=document.getElementById('lessonName'); if(el&&d.lesson)el.value=d.lesson;\n  MANUAL=!!d.manual; COMMITTED=!!d.committed;\n  renderPreview();\n};\n\n\n/* ═══════════ محرك «صيد البالون» — مقلاع وفيزياء على Canvas ═══════════\n   المحرك منفصل عن المحتوى: لا سؤال مكتوبًا هنا — الأسئلة تأتي من مولّد\n   غراس (questions أعلاه) بالهيئة {q, options[4], correct}. والصوت مؤجَّل بقرار. */\nconst LIVES=3;\nconst PALETTE=[['#ff8fa3','#e5566f'],['#7ec8f0','#3d97cf'],['#ffd166','#eaa72b'],\n               ['#a8e6a1','#5fb85a'],['#c9a7f5','#9163d6'],['#ffb08a','#ef7b4c']];\nconst G=0.42, MAXPULL=130;\nconst rand=(a,b)=>a+Math.random()*(b-a);\n/* فيشر–ييتس يخلط كائنات الخيارات كاملة — وسم الصحيح يركب مع خياره فلا ينفصلان */\nconst fshuffle=a=>{for(let i=a.length-1;i>0;i--){const j=(Math.random()*(i+1))|0;[a[i],a[j]]=[a[j],a[i]];}return a;};\n\nlet bcv=null,bx=null,W=0,H=0,DPR=1,rafId=null;\nlet bState='idle', balloons=[], parts=[], projectile=null, trail=[];\nlet qIndex=0, bScore=0, lives=LIVES, order=[];\nlet anchor={x:0,y:0}, pull={x:0,y:0}, draggingB=false, canShoot=true;\nlet shake=0, sunT=0, R=46;\nconst CLOUDS=[];\n\nfunction bLayout(){ anchor.x=W/2; anchor.y=H-Math.max(140,H*0.22); R=Math.max(34,Math.min(54,Math.min(W,H)/11)); }\nfunction bResize(){\n  if(!bcv)return;\n  DPR=Math.min(window.devicePixelRatio||1,2);\n  W=bcv.clientWidth; H=bcv.clientHeight;\n  bcv.width=W*DPR; bcv.height=H*DPR;\n  bx.setTransform(DPR,0,0,DPR,0,0);\n  bLayout();\n}\nwindow.addEventListener('resize',()=>{ if(bState!=='idle') bResize(); });\n\nfunction buildRound(){\n  const q=questions[order[qIndex]];\n  /* نص خارجي → textContent حصراً */\n  document.getElementById('bqtext').textContent=q.q;\n  const bar=document.getElementById('bqbar');\n  bar.animate([{transform:'scale(.9)',opacity:.4},{transform:'scale(1)',opacity:1}],\n    {duration:380,easing:'cubic-bezier(.2,1.4,.4,1)'});\n  let opts=(q.options||[]).map((t,i)=>({text:String(t),correct:i===q.correct}));\n  opts=fshuffle(opts);\n  balloons=opts.map((o,i)=>{\n    const c=PALETTE[(i+qIndex)%PALETTE.length];\n    return {x:(W/(opts.length+1))*(i+1)+rand(-14,14), y:H*0.66-i*(H*0.085)+rand(-14,14),\n      vy:rand(0.26,0.45), phase:rand(0,Math.PI*2), amp:rand(10,22),\n      text:o.text, correct:o.correct, c1:c[0], c2:c[1], alive:true, scale:1};\n  });\n}\nfunction burst(x,y,c1,c2,n=26){\n  for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(2,8.5);\n    parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-2,r:rand(3,8),life:1,c:Math.random()<.5?c1:c2});}\n}\nfunction drawSky(){const g=bx.createLinearGradient(0,0,0,H);\n  g.addColorStop(0,'#bfe9ff');g.addColorStop(.55,'#e6f6ff');g.addColorStop(1,'#fdf3e3');\n  bx.fillStyle=g;bx.fillRect(0,0,W,H);}\nfunction drawSun(){\n  const x=W*0.82,y=H*0.13,r=Math.min(W,H)*0.075; sunT+=0.012;\n  bx.save();bx.translate(x,y);bx.globalAlpha=.35;\n  for(let i=0;i<12;i++){bx.rotate(Math.PI/6);bx.fillStyle='#ffd98a';\n    const l=r*1.35+Math.sin(sunT+i)*r*0.12;\n    bx.beginPath();bx.ellipse(0,-l,r*.13,r*.34,0,0,7);bx.fill();}\n  bx.restore();\n  const g=bx.createRadialGradient(x-r*.3,y-r*.3,r*.2,x,y,r);\n  g.addColorStop(0,'#fff3c4');g.addColorStop(1,'#fbc23c');\n  bx.fillStyle=g;bx.beginPath();bx.arc(x,y,r,0,7);bx.fill();\n}\nfunction drawClouds(){\n  if(!CLOUDS.length)for(let i=0;i<5;i++)CLOUDS.push({x:Math.random(),y:rand(.14,.46),s:rand(.6,1.25),v:rand(.00004,.00012)});\n  bx.fillStyle='rgba(255,255,255,.85)';\n  for(const c of CLOUDS){c.x+=c.v;if(c.x>1.25)c.x=-.25;\n    const x=c.x*W,y=c.y*H,s=c.s*Math.min(W,H)*0.05;\n    bx.beginPath();bx.arc(x,y,s,0,7);bx.arc(x+s*.9,y+s*.15,s*.75,0,7);\n    bx.arc(x-s*.9,y+s*.2,s*.65,0,7);bx.arc(x,y+s*.4,s*.8,0,7);bx.fill();}\n}\nfunction drawSea(){\n  const top=H*0.72,sand=H*0.88;\n  const g=bx.createLinearGradient(0,top,0,sand+20);\n  g.addColorStop(0,'#6fcdec');g.addColorStop(1,'#2b8fc4');\n  bx.fillStyle=g;bx.beginPath();bx.moveTo(0,top);\n  for(let x=0;x<=W;x+=12)bx.lineTo(x,top+Math.sin(x*0.018+sunT*2.2)*5);\n  bx.lineTo(W,H);bx.lineTo(0,H);bx.closePath();bx.fill();\n  bx.strokeStyle='rgba(255,255,255,.32)';bx.lineWidth=2;\n  for(let i=1;i<=2;i++){bx.beginPath();\n    for(let x=0;x<=W;x+=12)bx.lineTo(x,top+i*(H*0.05)+Math.sin(x*0.02+sunT*2+i)*4);\n    bx.stroke();}\n  const sg=bx.createLinearGradient(0,sand-40,0,H);\n  sg.addColorStop(0,'#ffeccb');sg.addColorStop(1,'#efc98f');\n  bx.fillStyle=sg;bx.beginPath();bx.moveTo(0,sand+14);\n  bx.quadraticCurveTo(W*0.5,sand-38,W,sand+14);\n  bx.lineTo(W,H);bx.lineTo(0,H);bx.closePath();bx.fill();\n  bx.strokeStyle='rgba(255,255,255,.7)';bx.lineWidth=3;\n  bx.beginPath();bx.moveTo(0,sand+14);\n  bx.quadraticCurveTo(W*0.5,sand-38,W,sand+14);bx.stroke();\n}\nfunction drawBalloon(b){\n  const sway=Math.sin(b.phase)*b.amp;\n  const x=b.x+sway,y=b.y,r=R*b.scale;\n  bx.strokeStyle='rgba(90,110,130,.45)';bx.lineWidth=1.6;\n  bx.beginPath();bx.moveTo(x,y+r*1.08);\n  bx.quadraticCurveTo(x+sway*0.5,y+r*1.6,x,y+r*2.1);bx.stroke();\n  const g=bx.createRadialGradient(x-r*.35,y-r*.4,r*.15,x,y,r*1.15);\n  g.addColorStop(0,'#ffffff');g.addColorStop(.22,b.c1);g.addColorStop(1,b.c2);\n  bx.save();bx.shadowColor='rgba(30,60,90,.18)';bx.shadowBlur=14;bx.shadowOffsetY=6;\n  bx.fillStyle=g;bx.beginPath();bx.ellipse(x,y,r*0.88,r,0,0,7);bx.fill();bx.restore();\n  bx.fillStyle=b.c2;\n  bx.beginPath();bx.moveTo(x-r*.11,y+r*.99);bx.lineTo(x+r*.11,y+r*.99);\n  bx.lineTo(x,y+r*1.16);bx.closePath();bx.fill();\n  bx.fillStyle='rgba(255,255,255,.5)';\n  bx.beginPath();bx.ellipse(x-r*.34,y-r*.36,r*.14,r*.24,-0.5,0,7);bx.fill();\n  b._sx=x;\n  drawOptText(b,x,y,r);\n}\n/* النص يُرسم على Canvas — لا HTML هنا أصلًا.\n   القصير يتوسط البالون، والطويل لا يُحشر: يُعرض في بطاقة بيضاء يحملها\n   خيط البالون. الهدف المصاب يبقى البالون نفسه — البطاقة لافتة لا هدف. */\nfunction drawOptText(b,x,y,r){\n  const fs=fitFont(b.text,r*1.5,r*0.52,Math.max(12,r*0.3));\n  if(fs){\n    bx.textAlign='center';bx.textBaseline='middle';\n    bx.font=`800 ${fs}px 'Cairo',system-ui,sans-serif`;\n    bx.lineWidth=fs*0.22;bx.strokeStyle='rgba(0,0,0,.16)';\n    bx.strokeText(b.text,x,y);bx.fillStyle='#fff';bx.fillText(b.text,x,y);\n    return;\n  }\n  const n=Math.max(1,balloons.length);\n  const maxW=Math.min(Math.max(120,W/n-14),230);\n  const cfs=Math.max(12,Math.min(15,r*0.32));\n  bx.font=`800 ${cfs}px 'Cairo',system-ui,sans-serif`;\n  const lines=wrapText(b.text,maxW-18,3);\n  const lh=cfs*1.35;\n  let tw=0;for(const t of lines){const w2=bx.measureText(t).width;if(w2>tw)tw=w2;}\n  const cw=Math.min(maxW,tw+18), ch=lines.length*lh+12;\n  const cx0=x-cw/2, cy0=y+r*2.15;\n  bx.save();\n  bx.shadowColor='rgba(30,60,90,.2)';bx.shadowBlur=8;bx.shadowOffsetY=3;\n  bx.fillStyle='rgba(255,255,255,.95)';\n  roundRect(cx0,cy0,cw,ch,10);bx.fill();\n  bx.restore();\n  bx.strokeStyle=b.c2;bx.lineWidth=2;roundRect(cx0,cy0,cw,ch,10);bx.stroke();\n  bx.fillStyle='#1c3d5a';bx.textAlign='center';bx.textBaseline='middle';\n  bx.save();bx.direction='rtl';\n  for(let i=0;i<lines.length;i++)bx.fillText(lines[i],x,cy0+6+lh*(i+.5));\n  bx.restore();\n}\nfunction fitFont(t,maxW,fs,minFs){\n  for(fs=Math.floor(fs);fs>=minFs;fs--){\n    bx.font=`800 ${fs}px 'Cairo',system-ui,sans-serif`;\n    if(bx.measureText(t).width<=maxW)return fs;\n  }\n  return 0;\n}\nfunction wrapText(t,maxW,maxLines){\n  const words=String(t).split(/\\s+/).filter(Boolean),lines=[];let cur='';\n  for(const w of words){\n    const cand=cur?cur+' '+w:w;\n    if(!cur||bx.measureText(cand).width<=maxW)cur=cand;\n    else{lines.push(cur);cur=w;}\n  }\n  if(cur)lines.push(cur);\n  if(lines.length>maxLines){\n    lines.length=maxLines;let last=lines[maxLines-1];\n    while(last.length>1&&bx.measureText(last+'…').width>maxW)last=last.slice(0,-1);\n    lines[maxLines-1]=last+'…';\n  }\n  return lines;\n}\nfunction roundRect(x0,y0,w,h,rr){\n  bx.beginPath();bx.moveTo(x0+rr,y0);\n  bx.arcTo(x0+w,y0,x0+w,y0+h,rr);bx.arcTo(x0+w,y0+h,x0,y0+h,rr);\n  bx.arcTo(x0,y0+h,x0,y0,rr);bx.arcTo(x0,y0,x0+w,y0,rr);bx.closePath();\n}\nfunction drawSling(){\n  const w=R*0.62,h=R*1.5;\n  bx.strokeStyle='#8b5a2b';bx.lineCap='round';bx.lineWidth=Math.max(7,R*0.17);\n  bx.beginPath();bx.moveTo(anchor.x,anchor.y+h);bx.lineTo(anchor.x-w,anchor.y);bx.stroke();\n  bx.beginPath();bx.moveTo(anchor.x,anchor.y+h);bx.lineTo(anchor.x+w,anchor.y);bx.stroke();\n  bx.strokeStyle='#6d4520';\n  bx.beginPath();bx.moveTo(anchor.x,anchor.y+h);bx.lineTo(anchor.x,anchor.y+h*1.55);bx.stroke();\n  const px=anchor.x+pull.x,py=anchor.y+pull.y;\n  bx.strokeStyle='#c0563f';bx.lineWidth=Math.max(5,R*0.13);\n  bx.beginPath();bx.moveTo(anchor.x-w,anchor.y);bx.lineTo(px,py);bx.stroke();\n  bx.beginPath();bx.moveTo(anchor.x+w,anchor.y);bx.lineTo(px,py);bx.stroke();\n  if(!projectile){\n    const g=bx.createRadialGradient(px-5,py-6,3,px,py,R*0.42);\n    g.addColorStop(0,'#fff2b8');g.addColorStop(1,'#e9962c');\n    bx.fillStyle=g;bx.beginPath();bx.arc(px,py,R*0.4,0,7);bx.fill();\n  }\n  if(draggingB){\n    const vx=-pull.x*0.19,vy=-pull.y*0.19;\n    bx.fillStyle='rgba(255,255,255,.55)';\n    let sx=px,sy=py,dx=vx,dy=vy;\n    for(let i=0;i<26;i++){sx+=dx*2.4;sy+=dy*2.4;dy+=G*2.4;\n      if(sy>H||sx<0||sx>W)break;\n      bx.beginPath();bx.arc(sx,sy,Math.max(2,4-i*0.09),0,7);bx.fill();}\n  }\n}\nfunction drawProjectile(){\n  if(!projectile)return;\n  trail.push({x:projectile.x,y:projectile.y});\n  if(trail.length>14)trail.shift();\n  trail.forEach((t,i)=>{bx.fillStyle=`rgba(255,214,120,${i/trail.length*0.4})`;\n    bx.beginPath();bx.arc(t.x,t.y,R*0.32*(i/trail.length),0,7);bx.fill();});\n  const g=bx.createRadialGradient(projectile.x-5,projectile.y-6,3,projectile.x,projectile.y,R*0.42);\n  g.addColorStop(0,'#fff2b8');g.addColorStop(1,'#e9962c');\n  bx.fillStyle=g;bx.beginPath();bx.arc(projectile.x,projectile.y,R*0.4,0,7);bx.fill();\n}\nfunction bLoop(){\n  rafId=requestAnimationFrame(bLoop);\n  bx.save();\n  if(shake>0){bx.translate(rand(-shake,shake),rand(-shake,shake));shake*=0.86;if(shake<0.3)shake=0;}\n  drawSky();drawSun();drawClouds();\n  if(bState==='play'){\n    for(const b of balloons){\n      if(!b.alive)continue;\n      b.y-=b.vy;b.phase+=0.018;\n      if(b.y<H*0.22)b.y=H*0.76;\n      drawBalloon(b);\n    }\n  }\n  drawSea();\n  if(bState==='play'){drawSling();drawProjectile();}\n  if(projectile){\n    projectile.x+=projectile.vx;projectile.y+=projectile.vy;projectile.vy+=G;\n    for(const b of balloons){\n      if(!b.alive)continue;\n      const dx=projectile.x-b._sx,dy=projectile.y-b.y;\n      if(dx*dx+dy*dy<(R*0.92)*(R*0.92)){bHit(b);break;}\n    }\n    if(projectile&&(projectile.y>H+80||projectile.x<-90||projectile.x>W+90))bReload();\n  }\n  for(let i=parts.length-1;i>=0;i--){\n    const p=parts[i];\n    p.x+=p.vx;p.y+=p.vy;p.vy+=0.28;p.vx*=0.99;p.life-=0.018;\n    if(p.life<=0){parts.splice(i,1);continue;}\n    bx.globalAlpha=Math.max(0,p.life);bx.fillStyle=p.c;\n    bx.beginPath();bx.arc(p.x,p.y,p.r*p.life,0,7);bx.fill();bx.globalAlpha=1;\n  }\n  bx.restore();\n}\n\n/* ═══ مؤثرات صوتية خفيفة — نفس محرك WebAudio في ألعاب غراس ═══\n   الـAudioContext يُنشأ كسولًا عند أول مؤثر، وأول مؤثر لا يقع إلا بعد\n   لمسة المستخدم (إطلاق/إصابة) — فقيد Safari/iPad على التشغيل محترم. */\nlet AC=null;\nfunction ac(){if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();return AC}\nfunction tone(freq,dur,type,vol,when,slide){\n  type=type||'sine';vol=vol==null?.16:vol;when=when||0;slide=slide||0;\n  try{\n    const c=ac(),o=c.createOscillator(),g=c.createGain();\n    o.type=type;o.frequency.setValueAtTime(freq,c.currentTime+when);\n    if(slide)o.frequency.exponentialRampToValueAtTime(slide,c.currentTime+when+dur);\n    g.gain.setValueAtTime(vol,c.currentTime+when);\n    g.gain.exponentialRampToValueAtTime(.001,c.currentTime+when+dur);\n    o.connect(g);g.connect(c.destination);\n    o.start(c.currentTime+when);o.stop(c.currentTime+when+dur+.05);\n  }catch(_){}\n}\nconst SFX={\n  launch(){tone(280,.2,'sine',.11,0,760)},\n  correct(){tone(523,.12,'triangle',.2);tone(659,.12,'triangle',.2,.09);tone(784,.3,'triangle',.22,.18)},\n  wrong(){tone(220,.22,'sawtooth',.12,0,140)},\n  win(){[523,659,784,1047,1319].forEach((f,i)=>tone(f,.2,'triangle',.18,i*.13))}\n};\n\nfunction bHit(b){\n  b.alive=false;\n  burst(b._sx,b.y,b.c1,b.c2,b.correct?34:20);\n  projectile=null;trail=[];\n  if(b.correct){\n    bScore+=10;shake=4;SFX.correct();bFlash('أحسنت! ✨','#3ba55d');\n    setTimeout(bNextQ,850);\n  }else{\n    lives--;shake=11;SFX.wrong();bFlash('حاول مرة أخرى','#e05252');bHUD();\n    if(lives<=0){setTimeout(()=>bGameOver(false),800);return;}\n    setTimeout(()=>{b.alive=true;b.y=H*0.76;},900);\n    canShoot=true;\n  }\n  bHUD();\n}\nfunction bReload(){projectile=null;trail=[];canShoot=true;}\nfunction bNextQ(){\n  qIndex++;\n  if(qIndex>=order.length){bGameOver(true);return;}\n  buildRound();bReload();\n}\nfunction bFlash(t,c){\n  const f=document.getElementById('bflash');\n  f.textContent=t;f.style.color=c;\n  f.classList.remove('go');void f.offsetWidth;f.classList.add('go');\n}\nfunction bHUD(){\n  document.getElementById('bscore').textContent='النقاط '+AR(bScore);\n  document.getElementById('bhearts').textContent='❤️'.repeat(Math.max(0,lives))+'🤍'.repeat(Math.max(0,LIVES-lives));\n}\nfunction bGameOver(won){\n  bState='over';\n  const win=won&&lives>0;\n  if(win)SFX.win();\n  document.getElementById('bendEmoji').textContent=win?'🏆':'💪';\n  document.getElementById('bendTitle').textContent=win?'بطل غراس!':'قريب جدًا!';\n  document.getElementById('bscoreBig').textContent=AR(bScore)+' نقطة';\n  document.getElementById('bendMsg').textContent=win\n    ?'أجبت على كل الأسئلة — استمر على هذا التألق ✨'\n    :'كل محاولة تقرّبك من الإتقان، جرّب مرة أخرى!';\n  document.getElementById('bend').classList.remove('hide');\n}\nfunction startPlay(){\n  bScore=0;lives=LIVES;qIndex=0;\n  order=questions.map((_,i)=>i);fshuffle(order);\n  parts=[];projectile=null;trail=[];pull={x:0,y:0};canShoot=true;\n  bHUD();buildRound();\n  document.getElementById('bstart').classList.add('hide');\n  document.getElementById('bend').classList.add('hide');\n  bState='play';\n}\nfunction bPos(e){\n  const r=bcv.getBoundingClientRect();\n  const t=e.touches?e.touches[0]:e;\n  return {x:t.clientX-r.left,y:t.clientY-r.top};\n}\nfunction bDown(e){\n  if(bState!=='play'||!canShoot||projectile)return;\n  const p=bPos(e);\n  if(Math.hypot(p.x-anchor.x-pull.x,p.y-anchor.y-pull.y)<R*3)draggingB=true;\n  e.preventDefault();\n}\nfunction bMove(e){\n  if(!draggingB)return;\n  const p=bPos(e);\n  let dx=p.x-anchor.x,dy=p.y-anchor.y;\n  const d=Math.hypot(dx,dy);\n  if(d>MAXPULL){dx=dx/d*MAXPULL;dy=dy/d*MAXPULL;}\n  if(dy<0)dy*=0.35;\n  pull={x:dx,y:dy};\n  e.preventDefault();\n}\nfunction bUp(e){\n  if(!draggingB)return;\n  draggingB=false;\n  const power=Math.hypot(pull.x,pull.y);\n  if(power>16){\n    projectile={x:anchor.x+pull.x,y:anchor.y+pull.y,vx:-pull.x*0.19,vy:-pull.y*0.19};\n    canShoot=false;trail=[];SFX.launch();\n  }\n  pull={x:0,y:0};\n  if(e.cancelable)e.preventDefault();\n}\nlet engineBound=false;\nfunction initEngine(){\n  bcv=document.getElementById('bcv');bx=bcv.getContext('2d');\n  bResize();\n  if(!engineBound){\n    engineBound=true;\n    bcv.addEventListener('mousedown',bDown);window.addEventListener('mousemove',bMove);window.addEventListener('mouseup',bUp);\n    bcv.addEventListener('touchstart',bDown,{passive:false});\n    window.addEventListener('touchmove',bMove,{passive:false});\n    window.addEventListener('touchend',bUp,{passive:false});\n  }\n  if(!rafId)bLoop();\n}\n\n/* ---------- فتح اللعبة وإغلاقها (الخصم هنا — كالمليون حرفيًا) ---------- */\nlet PREVIEWING=false;\n/* المعاينة تشغّل المحرك نفسه بلا خصم وبلا COMMITTED — التثبيت وحده يستهلك */\nasync function openGame(preview){\n  if(!questions.length){showErr('أنشئ الأسئلة من درسك أولًا 🌱');return;}\n  PREVIEWING=!!preview;\n  const badge=document.getElementById('bprev'); if(badge)badge.style.display=PREVIEWING?'':'none';\n  if(!PREVIEWING && !COMMITTED){\n    const _c=await consumeCredit();\n    if(!_c.ok){ showBuy(); return; }\n    COMMITTED=true;\n    if(!_c.unlimited && typeof _c.remaining==='number'){ CREDITS=_c.remaining; }\n    updateCreditBadge();\n    try{saveGame();}catch(_){}\n    try{if(window.GHLib){GHLib.commitSave();}}catch(_){}\n  }\n  document.getElementById('game').classList.add('show');\n  document.body.style.overflow='hidden';\n  bState='idle';\n  document.getElementById('bstart').classList.remove('hide');\n  document.getElementById('bend').classList.add('hide');\n  initEngine();\n}\nfunction closeGame(){\n  bState='idle';\n  if(rafId){cancelAnimationFrame(rafId);rafId=null;}\n  document.getElementById('game').classList.remove('show');\n  document.body.style.overflow='';\n}\n\n/* ---------- نظام رصيد الألعاب ---------- */\nasync function consumeCredit(){\n  if(IS_ADMIN) return {ok:true,unlimited:true};\n  try{\n    const r=await fetch('/api/game-consume',{method:'POST'});\n    const d=await r.json();\n    if(!d.ok) return {ok:false,error:d.error};\n    return {ok:true,remaining:d.remaining,unlimited:d.unlimited};\n  }catch(_){ return {ok:false,error:'net'}; }\n}\nfunction updateCreditBadge(){\n  const el=document.getElementById('creditBadge');\n  if(!el)return;\n  if(IS_ADMIN){ el.innerHTML='♾️ رصيد غير محدود'; el.className='cbadge admin'; return; }\n  el.innerHTML='🎟️ رصيدك: <b>'+AR(CREDITS)+'</b> '+(CREDITS===1?'لعبة':'ألعاب');\n  el.className='cbadge'+(CREDITS<=0?' empty':'');\n  try{var _fb=document.getElementById('freeBanner'); if(_fb)_fb.style.display=(!IS_ADMIN && CREDITS===1)?'block':'none';}catch(e){}\n}\nfunction showBuy(){\n  let m=document.getElementById('buyModal');\n  if(!m){\n    m=document.createElement('div'); m.id='buyModal'; m.className='buy-ov';\n    m.innerHTML=`<div class=\"buy-card\">\n      <button class=\"buy-x\" onclick=\"closeBuy()\">✕</button>\n      <div class=\"buy-seed\">🎟️</div>\n      <h3>خلص رصيد الألعاب</h3>\n      <p>لإنشاء لعبة جديدة من درسك، اختر باقة الرصيد المناسبة:</p>\n      <div class=\"buy-opts\">\n        <button class=\"buy-opt\" onclick=\"buyGame(1)\">\n          <b>لعبة واحدة</b><span class=\"pr\">٢ د.ك</span>\n        </button>\n        <button class=\"buy-opt best\" onclick=\"buyGame(5)\">\n          <span class=\"tag\">الأوفر</span>\n          <b>٥ ألعاب</b><span class=\"pr\">٨ د.ك</span><small>١.٦ د.ك للعبة</small>\n        </button>\n      </div>\n      <p class=\"buy-note\">التفعيل حالياً عبر إدارة غراس المعلم، والدفع الإلكتروني المباشر قريباً 🌱</p>\n    </div>`;\n    document.body.appendChild(m);\n  }\n  m.classList.add('show');\n}\nfunction closeBuy(){ const m=document.getElementById('buyModal'); if(m)m.classList.remove('show'); }\nfunction buyGame(n){\n  closeBuy();\n  alert(n===1\n    ? '🎟️ لشراء لعبة واحدة (٢ د.ك): يرجى التواصل مع إدارة غراس المعلم لتفعيل الرصيد.\\nوقريباً يصير الدفع مباشرة داخل التطبيق.'\n    : '🎟️ لشراء باقة ٥ ألعاب (٨ د.ك): يرجى التواصل مع إدارة غراس المعلم لتفعيل الرصيد.\\nوقريباً يصير الدفع مباشرة داخل التطبيق.');\n}\ntry{ updateCreditBadge(); }catch(_){}\n\n\n/* ===== مكتبة ألعابي المحفوظة ===== */\n\n/* ===================== GHIRAS-LIBRARY : ألعابي المحفوظة ===================== */\n(function(){\n  const TYPE='balloons';                   // نوع اللعبة (يُستبدل عند البناء)\n  const LABEL='صيد البالون';             // اسم اللعبة للعرض\n  const API='/api/saved-games';\n  const arNum=(n)=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n  window.__libCurId = window.__libCurId || null;\n\n  // ---------- بناء الواجهة ----------\n  const css=`\n  #libFab{position:fixed;bottom:18px;inset-inline-start:18px;z-index:900;display:inline-flex;align-items:center;gap:8px;\n    background:linear-gradient(180deg,#FFE9A8,#F0C24C);color:#5A3E00;font-weight:800;font-size:.95rem;font-family:inherit;\n    padding:12px 18px;border:none;border-radius:999px;box-shadow:0 8px 22px rgba(217,162,22,.4);cursor:pointer;transition:transform .15s}\n  #libFab:hover{transform:translateY(-2px) scale(1.03)}\n  #libFab .cnt{background:#fff;color:#B98900;border-radius:999px;min-width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.8rem;padding:0 6px}\n  #libBg{position:fixed;inset:0;background:rgba(18,24,40,.55);z-index:950;display:none;align-items:center;justify-content:center;padding:18px;backdrop-filter:blur(3px)}\n  #libBg.on{display:flex}\n  #libCard{background:#fff;border-radius:24px;max-width:560px;width:100%;max-height:82vh;display:flex;flex-direction:column;box-shadow:0 24px 60px rgba(0,0,0,.35);overflow:hidden;font-family:inherit;direction:rtl}\n  #libHead{background:linear-gradient(180deg,#FFF6DC,#FDE9B8);padding:18px 20px;display:flex;align-items:center;justify-content:space-between}\n  #libHead h3{margin:0;color:#5A3E00;font-size:1.15rem;font-weight:800}\n  #libHead .x{background:#fff;border:none;width:34px;height:34px;border-radius:50%;font-size:1.1rem;cursor:pointer;color:#8a6d1e;box-shadow:0 3px 8px rgba(0,0,0,.12)}\n  #libBody{padding:16px 18px;overflow:auto}\n  .libItem{display:flex;align-items:center;gap:12px;background:#F8FAFF;border:1.5px solid #E7EDF5;border-radius:16px;padding:12px 14px;margin-bottom:10px}\n  .libItem .ic{font-size:1.6rem}\n  .libItem .mid{flex:1;min-width:0}\n  .libItem .t{font-weight:800;color:#22314B;font-size:1rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .libItem .s{font-size:.78rem;color:#8794A6;font-weight:700;margin-top:2px}\n  .libItem .op{background:linear-gradient(180deg,#7FD79A,#49B96E);color:#fff;border:none;font-weight:800;font-family:inherit;\n    padding:9px 16px;border-radius:12px;cursor:pointer;font-size:.9rem;white-space:nowrap}\n  .libItem .dl{background:#fff;border:1.5px solid #F2C4C4;color:#D45B5B;width:38px;height:38px;border-radius:12px;cursor:pointer;font-size:1rem}\n  .libEmpty{text-align:center;color:#8794A6;font-weight:700;padding:34px 10px;line-height:1.9}\n  .libToast{position:fixed;bottom:78px;inset-inline-start:18px;z-index:980;background:#2E7D46;color:#fff;font-weight:800;\n    font-family:inherit;padding:11px 18px;border-radius:14px;box-shadow:0 8px 20px rgba(0,0,0,.25);opacity:0;transform:translateY(8px);transition:all .25s}\n  .libToast.on{opacity:1;transform:translateY(0)}\n  @media(max-width:520px){#libFab span.tx{display:none}}\n  `;\n  const st=document.createElement('style'); st.textContent=css; document.head.appendChild(st);\n\n  const fab=document.createElement('button'); fab.id='libFab';\n  fab.innerHTML=`📚 <span class=\"tx\">ألعابي المحفوظة</span> <span class=\"cnt\" id=\"libCnt\">٠</span>`;\n  fab.onclick=open;\n  const bg=document.createElement('div'); bg.id='libBg';\n  bg.innerHTML=`<div id=\"libCard\">\n     <div id=\"libHead\"><h3>📚 ألعابي المحفوظة — ${LABEL}</h3><button class=\"x\" onclick=\"GHLib.close()\">✕</button></div>\n     <div id=\"libBody\"><div class=\"libEmpty\">جارِ التحميل…</div></div>\n   </div>`;\n  bg.addEventListener('click',e=>{ if(e.target===bg) close(); });\n  function mount(){ if(!document.body){ return setTimeout(mount,50); } document.body.appendChild(fab); document.body.appendChild(bg); refreshCount(); }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',mount); else mount();\n\n  // ---------- شبكة ----------\n  async function jget(u){ const r=await fetch(u); if(!r.ok) throw new Error('http'); return r.json(); }\n  async function listGames(){ try{ const d=await jget(API+'?type='+TYPE); return d.games||[]; }catch(e){ return null; } }\n\n  let cache=[];\n  async function refreshCount(){ const g=await listGames(); if(g===null)return; cache=g; const c=document.getElementById('libCnt'); if(c)c.textContent=arNum(g.length); }\n\n  function open(){ bg.classList.add('on'); render(); }\n  function close(){ bg.classList.remove('on'); }\n\n  async function render(){\n    const body=document.getElementById('libBody');\n    body.innerHTML=`<div class=\"libEmpty\">جارِ التحميل…</div>`;\n    const g=await listGames();\n    if(g===null){ body.innerHTML=`<div class=\"libEmpty\">تعذّر الاتصال. تأكد من تسجيل الدخول وحاول مرة أخرى.</div>`; return; }\n    cache=g;\n    const c=document.getElementById('libCnt'); if(c)c.textContent=arNum(g.length);\n    if(!g.length){ body.innerHTML=`<div class=\"libEmpty\">ما عندك ألعاب محفوظة بعد 🌱<br>أنشئ لعبة وبتنحفظ هنا تلقائيًا لترجع لها أي وقت.</div>`; return; }\n    body.innerHTML=g.map(it=>{\n      const dt=fmt(it.updated_at);\n      return `<div class=\"libItem\" data-id=\"${it.id}\">\n        <span class=\"ic\">${icon()}</span>\n        <div class=\"mid\"><div class=\"t\">${esc(it.title||'لعبة')}</div><div class=\"s\">آخر تحديث: ${dt}</div></div>\n        <button class=\"op\" onclick=\"GHLib.load('${it.id}')\">▶️ افتح</button>\n        <button class=\"dl\" title=\"حذف\" onclick=\"GHLib.del('${it.id}',event)\">🗑️</button>\n      </div>`;\n    }).join('');\n  }\n\n  function icon(){ return ({millionaire:'🏆',snake:'🎲',xo:'⭕',sinjim:'🧠',balloons:'🎈'})[TYPE]||'🎮'; }\n  function esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\n  function fmt(iso){ try{ const d=new Date(iso); const D=arNum(d.getDate()), M=arNum(d.getMonth()+1), Y=arNum(d.getFullYear()); return `${D}/${M}/${Y}`; }catch(e){ return '—'; } }\n\n  function toast(msg){ const t=document.createElement('div'); t.className='libToast'; t.textContent=msg; document.body.appendChild(t);\n    requestAnimationFrame(()=>t.classList.add('on')); setTimeout(()=>{t.classList.remove('on'); setTimeout(()=>t.remove(),300);},2200); }\n\n  // ---------- حفظ تلقائي ----------\n  function newGame(){ window.__libCurId=null; }  // يُستدعى عند إنشاء لعبة جديدة\n\n  async function save(){\n    if(typeof window.__libGetData!=='function') return;\n    const g=window.__libGetData(); if(!g||!g.data) return;\n    try{\n      const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},\n        body:JSON.stringify({id:window.__libCurId||undefined, game_type:TYPE, title:g.title||'لعبة', data:g.data})});\n      const d=await r.json(); if(d&&d.id){ window.__libCurId=d.id; refreshCount(); }\n    }catch(e){}\n  }\n\n  // حفظ عند اللعب ثم بدء لعبة جديدة (يمنع الكتابة فوق اللعبة المدفوعة)\n  async function commitSave(){ await save(); newGame(); }\n\n  async function load(id){\n    const it=cache.find(x=>x.id===id); if(!it) return;\n    if(typeof window.__libApply==='function'){ try{ window.__libApply(it.data); }catch(e){} }\n    window.__libCurId=id; close(); toast('✅ فُتحت اللعبة — جاهزة للّعب');\n  }\n\n  async function del(id,ev){ if(ev)ev.stopPropagation();\n    try{ await fetch(API+'?id='+encodeURIComponent(id),{method:'DELETE'}); }catch(e){}\n    cache=cache.filter(x=>x.id!==id); render(); refreshCount();\n  }\n\n  window.GHLib={open,close,load,del,save,newGame,commitSave,refreshCount};\n})();\n\n\n/* ===== تعديل الأسئلة ===== */\n\n/* ===================== GHIRAS-QEDIT : تعديل الأسئلة بعد التوليد ===================== */\n(function(){\n  const arNum=(n)=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n\n  const css=`\n  .qedit-btn{margin-top:8px;display:inline-flex;align-items:center;gap:5px;background:#EEF3FF;border:1.5px solid #C9D8F2;\n    color:#2C4A78;font-weight:800;font-family:inherit;font-size:.82rem;padding:6px 12px;border-radius:10px;cursor:pointer;transition:.15s}\n  .qedit-btn:hover{background:#E1EBFC;border-color:#A9C4EC}\n  #qeBg{position:fixed;inset:0;background:rgba(18,24,40,.55);z-index:960;display:none;align-items:center;justify-content:center;padding:18px;backdrop-filter:blur(3px)}\n  #qeBg.on{display:flex}\n  #qeCard{background:#fff;border-radius:22px;max-width:560px;width:100%;max-height:88vh;display:flex;flex-direction:column;\n    box-shadow:0 24px 60px rgba(0,0,0,.35);overflow:hidden;font-family:inherit;direction:rtl}\n  #qeHead{background:linear-gradient(180deg,#EAF1FF,#D8E6FB);padding:16px 20px;display:flex;align-items:center;justify-content:space-between}\n  #qeHead h3{margin:0;color:#26426E;font-size:1.1rem;font-weight:800}\n  #qeHead .x{background:#fff;border:none;width:32px;height:32px;border-radius:50%;font-size:1rem;cursor:pointer;color:#5b6b86;box-shadow:0 3px 8px rgba(0,0,0,.12)}\n  #qeBody{padding:18px 20px;overflow:auto}\n  .qe-lbl{font-weight:800;color:#33465F;font-size:.9rem;margin:0 0 6px}\n  #qeQ{width:100%;box-sizing:border-box;padding:12px 14px;border-radius:14px;border:2px solid #DDE6F0;font-family:inherit;\n    font-size:1.02rem;font-weight:700;color:#22314B;background:#F8FBFF;resize:vertical;min-height:64px;line-height:1.7}\n  #qeQ:focus{outline:none;border-color:#7FA8E0;background:#fff}\n  .qe-opt{display:flex;align-items:center;gap:10px;margin-bottom:10px}\n  .qe-opt input[type=radio]{width:22px;height:22px;accent-color:#2E7D46;flex:none;cursor:pointer}\n  .qe-opt input[type=text]{flex:1;padding:11px 13px;border-radius:12px;border:2px solid #DDE6F0;font-family:inherit;\n    font-size:1rem;font-weight:700;color:#22314B;background:#F8FBFF}\n  .qe-opt input[type=text]:focus{outline:none;border-color:#7FA8E0;background:#fff}\n  .qe-hint{font-size:.8rem;color:#8794A6;font-weight:700;margin:2px 0 14px}\n  .qe-actions{display:flex;gap:10px;justify-content:flex-start;flex-wrap:wrap;margin-top:6px}\n  .qe-save{background:linear-gradient(180deg,#7FD79A,#49B96E);color:#fff;border:none;font-weight:800;font-family:inherit;\n    padding:12px 24px;border-radius:14px;cursor:pointer;font-size:1rem}\n  .qe-cancel{background:#fff;border:2px solid #DDE6F0;color:#4A5A72;font-weight:800;font-family:inherit;padding:11px 20px;border-radius:14px;cursor:pointer}\n  .qe-err{color:#C0392B;font-weight:800;font-size:.85rem;margin-top:8px;min-height:18px}\n  .qeToast{position:fixed;bottom:20px;inset-inline-start:18px;z-index:980;background:#2E7D46;color:#fff;font-weight:800;\n    font-family:inherit;padding:11px 18px;border-radius:14px;box-shadow:0 8px 20px rgba(0,0,0,.25);opacity:0;transform:translateY(8px);transition:all .25s}\n  .qeToast.on{opacity:1;transform:translateY(0)}\n  `;\n  const st=document.createElement('style'); st.textContent=css; document.head.appendChild(st);\n\n  const bg=document.createElement('div'); bg.id='qeBg';\n  bg.innerHTML=`<div id=\"qeCard\">\n    <div id=\"qeHead\"><h3>✏️ تعديل السؤال</h3><button class=\"x\" onclick=\"QEdit.close()\">✕</button></div>\n    <div id=\"qeBody\"></div></div>`;\n  bg.addEventListener('click',e=>{ if(e.target===bg) close(); });\n  function mount(){ if(!document.body)return setTimeout(mount,50); document.body.appendChild(bg); }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',mount); else mount();\n\n  let curIdx=-1;\n\n  function qArr(){ try{ return questions; }catch(e){ return (window.questions||[]); } }\n\n  function decorate(){\n    const list=document.getElementById('qList'); if(!list)return;\n    const items=list.querySelectorAll('.q-item');\n    items.forEach((it,gi)=>{\n      if(it.querySelector('.qedit-btn'))return;\n      const b=document.createElement('button'); b.type='button'; b.className='qedit-btn'; b.textContent='✏️ تعديل';\n      b.onclick=(e)=>{ e.stopPropagation(); open(gi); };\n      it.appendChild(b);\n    });\n  }\n\n  function open(i){\n    const arr=qArr(); const q=arr[i]; if(!q)return; curIdx=i;\n    const opts=Array.isArray(q.options)?q.options:[];\n    const body=document.getElementById('qeBody');\n    body.innerHTML=`\n      <div class=\"qe-lbl\">نص السؤال</div>\n      <textarea id=\"qeQ\">${esc(q.q||'')}</textarea>\n      <div style=\"height:14px\"></div>\n      <div class=\"qe-lbl\">الخيارات — اختر الإجابة الصحيحة 👆</div>\n      <div class=\"qe-hint\">علّم الدائرة بجانب الإجابة الصحيحة</div>\n      ${opts.map((o,j)=>`<div class=\"qe-opt\">\n        <input type=\"radio\" name=\"qeCorrect\" value=\"${j}\" ${j===q.correct?'checked':''} title=\"الإجابة الصحيحة\">\n        <input type=\"text\" id=\"qeO${j}\" value=\"${esc(o)}\" placeholder=\"الخيار ${arNum(j+1)}\">\n      </div>`).join('')}\n      <div class=\"qe-err\" id=\"qeErr\"></div>\n      <div class=\"qe-actions\">\n        <button class=\"qe-save\" onclick=\"QEdit.save()\">💾 حفظ التعديل</button>\n        <button class=\"qe-cancel\" onclick=\"QEdit.close()\">إلغاء</button>\n      </div>`;\n    bg.classList.add('on');\n    setTimeout(()=>{ const t=document.getElementById('qeQ'); if(t)t.focus(); },60);\n  }\n\n  function save(){\n    const arr=qArr(); const q=arr[curIdx]; if(!q)return close();\n    const qt=(document.getElementById('qeQ').value||'').trim();\n    const n=(Array.isArray(q.options)?q.options:[]).length;\n    const opts=[]; for(let j=0;j<n;j++){ opts.push((document.getElementById('qeO'+j).value||'').trim()); }\n    const cor=+((document.querySelector('input[name=qeCorrect]:checked')||{value:'0'}).value);\n    const err=document.getElementById('qeErr');\n    if(!qt){ err.textContent='اكتب نص السؤال'; return; }\n    if(opts.some(o=>!o)){ err.textContent='املأ كل الخيارات'; return; }\n    // تعديل في المكان (يحافظ على الربط مع الفئات في سين جيم)\n    q.q=qt; q.options=opts; q.correct=cor;\n    close();\n    try{ renderPreview(); }catch(_){}\n    try{ if(window.GHLib) GHLib.save(); }catch(_){}\n    toast('✅ تم حفظ التعديل');\n  }\n\n  function close(){ bg.classList.remove('on'); curIdx=-1; }\n  function esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\n  function toast(m){ const t=document.createElement('div'); t.className='qeToast'; t.textContent=m; document.body.appendChild(t);\n    requestAnimationFrame(()=>t.classList.add('on')); setTimeout(()=>{t.classList.remove('on'); setTimeout(()=>t.remove(),300);},2000); }\n\n  window.QEdit={decorate,open,save,close};\n})();\n\nwindow.addEventListener('load',()=>{try{loadSaved();}catch(_){}});\n";

export default async function BalloonsPage() {
  const supabase = createServerSupabase();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect('/login?next=/balloons');

  const { data: profile } = await supabase
    .from('profiles')
    .select('role, status, game_credits')
    .eq('id', user.id)
    .single();

  const isAdmin = profile?.role === 'admin';
  const credits = profile?.game_credits ?? 0;
  if (!isAdmin && profile?.status === 'suspended') redirect('/');

  const boot = `window.__IS_ADMIN=${isAdmin ? 'true' : 'false'};window.__GAME_CREDITS=${isAdmin ? 9999 : credits};`;

  return (
    <>
      <a href="/games" id="ghiras-back-btn" style={{position:'fixed',top:10,left:10,zIndex:2147483647,display:'flex',alignItems:'center',gap:6,background:'rgba(65,96,63,.92)',color:'#fff',fontFamily:"Cairo,'Segoe UI',sans-serif",fontWeight:800,fontSize:13,lineHeight:1,padding:'9px 14px',borderRadius:999,textDecoration:'none',boxShadow:'0 4px 14px rgba(0,0,0,.28)'}}>← ألعاب غراس</a>
      <style dangerouslySetInnerHTML={{ __html: GAME_CSS }} />
      <div dangerouslySetInnerHTML={{ __html: GAME_BODY }} />
      <Script id="bg-boot" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: boot }} />
      <Script id="bg-main" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: GAME_JS }} />
    </>
  );
}
